#pragma once
#include <vector>
#include <random>
#include <cmath>
#include <algorithm>
#include <array>
#include <sstream>
#include <string>
#include "Scales.hpp"
#include "Euclidean.hpp"
#include "NeoRiemannian.hpp"
#include "../dsp/KSRandomizerCore.hpp"
#include "MelodicContourMemory.hpp"

namespace rasgo {

// Combines a Euclidean rhythmic gate pattern with scale-based random note
// selection -- the same idea as the original Kosmische Sequence.java
// (random note per step, drawn from a chosen scale, with steps randomly
// enabled/disabled), but with the gate pattern generated by Bjorklund's
// algorithm instead of a coin flip per step, and with a `density` knob
// (0..1, roughly "how full is the rhythm") that the narrative layer can
// drive over the course of a piece.
class StepSequencer {
public:
    enum class RhythmModel { Euclidean, Stochastic, Clustered, Irregular };
    enum class HarmonicModel { Modal, Functional, Jazz, Chromatic, Drone };

    void configure(int numSteps, Scale scale, int rootMidiNote, unsigned seed,
                   RhythmModel rhythmModel = RhythmModel::Euclidean,
                   double scaleBlendProbability = 0.10,
                   HarmonicModel harmonicModel = HarmonicModel::Modal) {
        numSteps_ = numSteps;
        scale_ = scale;
        rootMidiNote_ = rootMidiNote;
        lastMidiNote_ = rootMidiNote;
        rhythmModel_ = rhythmModel;
        harmonicModel_ = harmonicModel;
        rng_.seed(seed);
        ksRandomizer_.seed(seed + 4006u);
        notes_.assign(static_cast<size_t>(numSteps_), rootMidiNote_);
        gate_.assign(static_cast<size_t>(numSteps_), false);
        chooseScaleBlend(seed, scaleBlendProbability);
        chooseSequenceCharacter(seed);
        contourMemory_.configure(seed + 9600u, 4);
        phraseBarCount_ = 0;
        lastDegreeOffset_ = 0;
        firstRegenerate_ = true;
        regenerate(0.5);
        firstRegenerate_ = false;
    }

    // e.g. "Harmonic Minor" or "Harmonic Minor+Bebop(0.34)" -- same
    // transparency idea as GenerativeArc::templateDescription(), for
    // metadata: the scale you pick in the UI stays the piece's primary
    // (an instrument-tuning choice, same footing as bpm), but the seed can
    // still blend in a second one, so the WAV's metadata should say which.
    std::string scaleDescription() const {
        std::ostringstream s;
        s << (customPrimary_ ? customPrimaryDescription_ : scaleName(scale_));
        if (hasSecondaryScale_) s << "+" << scaleName(secondaryScale_) << "(" << blendAmount_ << ")";
        return s.str();
    }

    // Overrides the primary scale's degree table with an algorithmically
    // generated one (see SieveScale.hpp) instead of a catalog lookup --
    // called right after configure(), when a piece draws a generated scale
    // instead of picking from the researched repertoire. The secondary-
    // scale blend above is untouched (still drawn from the catalog), so a
    // generated scale can still cross-pollinate with a real one exactly
    // like any other primary would.
    void setCustomPrimaryScale(const ScaleTable &table, const std::string &description) {
        customPrimary_ = true;
        customPrimaryTable_ = table;
        customPrimaryDescription_ = description;
        // This is normally called immediately after configure(), before the
        // first piece bar is rendered. Do not let a pattern drawn from the
        // former catalog survive through Turing-machine lock: the next
        // regeneration must be a complete draw from the new collection.
        std::fill(notes_.begin(), notes_.end(), rootMidiNote_);
        std::fill(gate_.begin(), gate_.end(), false);
        lastDegreeIndex_ = 0;
        lastDegreeOffset_ = 0;
        firstRegenerate_ = true;
    }

    // The collection currently governing the primary melodic organism. Keep
    // this accessor as the contract boundary for dependent voices: a
    // generated Xenakis table must not silently collapse back to the catalog
    // merely because a consumer needs chord tones or a bass register.
    const ScaleTable &primaryScaleTable() const {
        return customPrimary_ ? customPrimaryTable_ : scaleTable(scale_);
    }

    // Regenerate both the rhythmic gate (via Euclidean rhythm, pulse count
    // derived from `density`) and the note choices (random draw from the
    // configured scale, with octave jitter) -- called once per bar so the
    // pattern feels stable within a bar but keeps evolving bar to bar as
    // the narrative arc's density target changes.
    //
    // octaveBias (roughly -1..1) skews which register the octave jitter
    // lands in -- the KS Synthesis 4006 Randomizer Core's "Probability"
    // idea (see KSRandomizerCore.hpp) put to use here rather than just
    // sitting idle: two biased coin draws per note decide whether the
    // octave jitter leans down, stays put, or leans up, instead of a flat
    // uniform -1/0/+1. At bias 0 this is statistically close to the old
    // uniform behaviour; away from 0 it lets the calling arc nudge the
    // melody's register up or down without ever forcing a specific note.
    void regenerate(double density, double octaveBias = 0.0) {
        int pulses = static_cast<int>(std::round(density * numSteps_));
        pulses = std::max(1, std::min(numSteps_ - 1, pulses));
        auto freshGate = generateGate(density, pulses);

        ksRandomizer_.setProbability(octaveBias);
        std::uniform_real_distribution<double> unit(0.0, 1.0);

        // Music Thing Modular's Turing Machine: instead of a fresh random
        // pattern every bar, a "lock" amount decides -- per step -- whether
        // that step keeps whatever it already had or gets redrawn. 0 is
        // this engine's old behaviour (fully fresh every bar); toward 1,
        // a pattern mostly persists and only a few steps mutate each bar,
        // so a theme can emerge and gradually evolve instead of the
        // sequence starting over from scratch every 16 steps. Forced to 0
        // on the very first call (nothing to keep yet).
        double effectiveLock = firstRegenerate_ ? 0.0 : lockAmount_;
        contourMemory_.beginBar();
        // Closer to 0 = strongly prefers small scale-degree jumps from the
        // previous note (Sapèl's "short jump" bias); closer to 1 = today's
        // uniform-random degree choice, jumps of any size equally likely.
        double closenessFactor = 0.15 + jumpiness_ * 0.85;

        for (int i = 0; i < numSteps_; ++i) {
            bool keepOld = unit(rng_) < effectiveLock;
            if (keepOld) continue; // gate_[i]/notes_[i] stay whatever they already were

            gate_[static_cast<size_t>(i)] = freshGate[static_cast<size_t>(i)];

            bool drawIsPrimary = !(hasSecondaryScale_ && unit(rng_) < blendAmount_);
            Scale drawScale = drawIsPrimary ? scale_ : secondaryScale_;
            const ScaleTable &table = (drawIsPrimary && customPrimary_) ? customPrimaryTable_ : scaleTable(drawScale);

            if (voiceLeadingEnabled_) {
                // A wholly different note-choice algorithm for the whole
                // piece (see chooseVoiceLeadingNote) -- mutually exclusive
                // with the degree-index/octaveSteps path below, the same
                // "one clean mode or the other, not layered" discipline as
                // modal shift vs. tonal modulation elsewhere in this
                // engine. Chord-tone/strong-beat weighting doesn't apply
                // here: this mode reasons in absolute semitones, not scale
                // degree indices, so blending the two would need degree-
                // index bookkeeping this path deliberately has no use for.
                lastMidiNote_ = chooseVoiceLeadingNote(table);
                notes_[static_cast<size_t>(i)] = lastMidiNote_;
                continue;
            }

            int degreeIndex;
            if (jumpiness_ >= 0.98) {
                std::uniform_int_distribution<int> degreeDist(0, table.length - 1);
                degreeIndex = degreeDist(rng_);
            } else {
                double weights[12]; // matches ScaleTable::degrees' size (12, since Chromatic needs all twelve)
                double total = 0.0;
                for (int j = 0; j < table.length; ++j) {
                    weights[j] = std::pow(closenessFactor, static_cast<double>(std::abs(j - lastDegreeIndex_)));
                    // A simple functional-harmony flavour: on a strong beat
                    // (see isStrongBeat), stable scale degrees (root/3rd/5th-
                    // ish -- table indices 0/2/4, or just 0/2 on 5-note
                    // scales) get pulled toward more strongly, so melodic
                    // weight lands on something chord-tone-like right where
                    // a listener's ear expects resolution; weak beats are
                    // untouched, free to keep wandering as passing tones.
                    // Off for about half of pieces (harmonicWeightEnabled_)
                    // and always off for the pure-uniform jumpiness>=0.98
                    // branch above -- a colour choice, not a rule imposed on
                    // every piece.
                    // With a chord progression running (see advanceChord()),
                    // "stable" moves with the current bar's chord (root/3rd/
                    // 5th built on whatever scale degree the progression is
                    // on right now) instead of always meaning the key's own
                    // I/III/V -- real harmonic rhythm, not a fixed target.
                    bool stableHere = chordProgressionEnabled_
                        ? isChordToneForTable(j, table)
                        : isStableDegree(j, table.length);
                    if (harmonicWeightEnabled_ && isStrongBeat(i) && stableHere) {
                        weights[j] *= (1.0 + strongBeatPull_);
                    }
                    weights[j] *= contourMemory_.pitchWeight(
                        table.degrees[static_cast<size_t>(j)],
                        lastDegreeOffset_, phraseBarCount_);
                    total += weights[j];
                }
                double roll = unit(rng_) * total;
                double acc = 0.0;
                degreeIndex = table.length - 1;
                for (int j = 0; j < table.length; ++j) {
                    acc += weights[j];
                    if (roll <= acc) { degreeIndex = j; break; }
                }
            }
            lastDegreeIndex_ = degreeIndex;
            int degree = table.degrees[static_cast<size_t>(degreeIndex)];
            lastDegreeOffset_ = degree;

            float drawA = ksRandomizer_.clock();
            float drawB = ksRandomizer_.clock();
            int octaveSteps = (drawA > 0.0f && drawB > 0.0f) ? 1
                             : (drawA < 0.0f && drawB < 0.0f) ? -1
                             : 0;
            notes_[static_cast<size_t>(i)] = rootMidiNote_ + degree + octaveSteps * 12;
        }

        // At the Turing Machine's other extreme (fully locked, left of
        // centre) the whole loop plays back reversed each cycle instead of
        // forward -- a seed-derived, rare embellishment on an already
        // highly-locked pattern, not something that fires on every piece.
        if (reverseOnLock_ && !firstRegenerate_) {
            std::reverse(gate_.begin(), gate_.end());
            std::reverse(notes_.begin(), notes_.end());
        }
        contourMemory_.finishBar();
        ++phraseBarCount_;
        if (phraseBarCount_ >= 4) phraseBarCount_ = 0;
    }

    void setRegisterOffset(int semitones) { registerOffset_ = semitones; }

    // A real tonal-centre shift mid-piece (root and, usually, the scale
    // itself) -- not the same thing as the secondary-scale blend above,
    // which mixes in a second colour around one fixed centre for the whole
    // piece. This actually moves the centre, so every voice keyed off
    // noteAt()/rootMidiNote_ (the melodic voice, the resonator, the
    // chiptune arpeggio) follows automatically from the very next note
    // drawn. If the incoming scale happens to match whatever the current
    // secondary blend scale already is, the blend is turned off rather
    // than silently blending a scale into itself.
    void modulateTo(int newRootMidiNote, Scale newScale) {
        const bool stateChanged = rootMidiNote_ != newRootMidiNote || scale_ != newScale;
        rootMidiNote_ = newRootMidiNote;
        scale_ = newScale;
        if (hasSecondaryScale_ && secondaryScale_ == scale_) hasSecondaryScale_ = false;
        if (stateChanged) {
            // A locked pattern belongs to the former tonal collection and
            // register. Do not let it leak through the modulation boundary:
            // the next bar must be drawn entirely from the new centre and
            // active collection. Phrase contour memory intentionally stays
            // alive; only stale note material is invalidated.
            std::fill(notes_.begin(), notes_.end(), rootMidiNote_);
            std::fill(gate_.begin(), gate_.end(), false);
            lastDegreeIndex_ = 0;
            lastDegreeOffset_ = 0;
            firstRegenerate_ = true;
        }
    }

    int rootMidiNote() const { return rootMidiNote_; }
    Scale scale() const { return scale_; }

    // Advances to the next chord in the progression -- call once per bar.
    // No-op if this piece didn't roll a chord progression (see
    // chooseSequenceCharacter): those pieces keep the fase-29 behaviour of
    // a fixed I/III/V "stable" target instead.
    void advanceChord() {
        if (!chordProgressionEnabled_) return;
        if (neoRiemannianEnabled_) {
            // A real chromatic triad wanders via Neo-Riemannian P/L/R
            // instead of stepping through a fixed roman-numeral list --
            // see NeoRiemannian.hpp. Each move changes exactly one pitch
            // class of the triad, a fluid, minimal-voice-leading harmonic
            // drift rather than the block-chord jumps a fixed progression
            // makes.
            double roll = std::uniform_real_distribution<double>(0.0, 1.0)(rng_);
            if (roll < 1.0 / 3.0) currentTriad_ = applyParallel(currentTriad_);
            else if (roll < 2.0 / 3.0) currentTriad_ = applyLeadingTone(currentTriad_);
            else currentTriad_ = applyRelative(currentTriad_);
            ++neoRiemannianOpCount_;
            return;
        }
        if (chordProgression_.empty()) return;
        currentChordDegreeIndex_ = chordProgression_[chordStep_ % chordProgression_.size()];
        ++chordStep_;
    }

    bool chordProgressionEnabled() const { return chordProgressionEnabled_; }
    int currentChordDegreeIndex() const { return currentChordDegreeIndex_; }

    // Non-mutating look-ahead for dependent phrase planners. Fixed
    // progressions expose the next chord root; Neo-Riemannian motion is
    // genuinely chosen only when advanceChord() consumes its RNG, so that
    // mode honestly reports the current root rather than predicting a move.
    int nextChordRootOffset() const {
        if (neoRiemannianEnabled_) return currentChordOffsets()[0];
        if (!chordProgressionEnabled_ || chordProgression_.empty()) return 0;
        const ScaleTable &table = primaryScaleTable();
        const int degreeIndex = chordProgression_[chordStep_ % chordProgression_.size()]
            % table.length;
        return table.degrees[static_cast<std::size_t>(degreeIndex)];
    }

    // Root/third/fifth/seventh of the chord actually sounding right now, as
    // real semitone offsets from rootMidiNote() (add to it for real notes)
    // -- for a consumer that wants concrete chord tones rather than a
    // scale-degree index or an abstract triad object (matches the real
    // Instruo Harmonaig's own root/3rd/5th/7th voicing, see CREDITS.md).
    // Works for both harmonic systems this sequencer runs: a fixed scale-
    // degree progression (thirds stacked within the active scale table, so
    // interval size follows the scale/mode -- the seventh is a third
    // stacked scale-degree beyond the fifth) and Neo-Riemannian's real
    // chromatic triad (fixed 4/3 and 7 semitone intervals, independent of
    // scale -- the seventh isn't part of that triad object, so a
    // conventional major-seventh-on-major/minor-seventh-on-minor interval
    // is added on top, the common "add a seventh to a plain triad" choice).
    // If no chord progression is running at all, falls back to the plain
    // tonic I/III/V/VII of the active scale -- same target
    // isChordToneForTable() already uses in that case.
    std::array<int, 4> currentChordOffsets() const {
        if (neoRiemannianEnabled_) {
            int rootOffset = mod12(currentTriad_.rootPc - rootMidiNote_);
            int thirdInterval = currentTriad_.isMajor ? 4 : 3;
            int seventhInterval = currentTriad_.isMajor ? 11 : 10;
            return { rootOffset, rootOffset + thirdInterval, rootOffset + 7, rootOffset + seventhInterval };
        }
        const ScaleTable &table = primaryScaleTable();
        int rootIdx = chordProgressionEnabled_ ? (currentChordDegreeIndex_ % table.length) : 0;
        int thirdIdx = (rootIdx + 2) % table.length;
        int fifthIdx = (rootIdx + 4) % table.length;
        int seventhIdx = (rootIdx + 6) % table.length;
        return { table.degrees[static_cast<size_t>(rootIdx)],
                 table.degrees[static_cast<size_t>(thirdIdx)],
                 table.degrees[static_cast<size_t>(fifthIdx)],
                 table.degrees[static_cast<size_t>(seventhIdx)] };
    }
    bool neoRiemannianEnabled() const { return neoRiemannianEnabled_; }
    int neoRiemannianOpCount() const { return neoRiemannianOpCount_; }
    std::string neoRiemannianDescription() const { return triadDescription(currentTriad_); }
    bool voiceLeadingEnabled() const { return voiceLeadingEnabled_; }
    int melodicContourDirection() const { return contourMemory_.direction(); }
    int melodicContourApexBar() const { return contourMemory_.apexBar(); }

    bool gateAt(int step) const { return gate_[static_cast<size_t>(step % numSteps_)]; }
    int noteAt(int step) const { return notes_[static_cast<size_t>(step % numSteps_)] + registerOffset_; }
    int numSteps() const { return numSteps_; }

    // Fase 89 -- real meter change: resizes the step grid alone (notes_/
    // gate_), preserving every other piece of state (rng stream, scale,
    // lock amount, sequence character, root) that calling configure()
    // again would otherwise reset. Called at a genuine arc-section
    // boundary when a section's meter differs from the piece's current
    // one; the very next regenerate() call (already invoked once per bar
    // regardless) fills in real content for the new length, so any
    // grown steps briefly hold a closed gate until that call turns some
    // on -- inaudible, never a stale note actually sounding.
    void setNumSteps(int newNumSteps) {
        if (newNumSteps == numSteps_) return;
        numSteps_ = newNumSteps;
        notes_.resize(static_cast<size_t>(numSteps_), rootMidiNote_);
        gate_.resize(static_cast<size_t>(numSteps_), false);
    }
    double lockAmount() const { return lockAmount_; }
    double jumpiness() const { return jumpiness_; }

    // Phase 118 game plan: memory and freedom now have a direct, audible
    // consequence in the sequence instead of merely changing the odds of
    // unrelated optional modules.  Blend with the seed-picked character so
    // the plan shapes an individual piece without becoming a fixed preset.
    void applyGameCharacter(double memory, double freedom, double risk) {
        memory = std::clamp(memory, 0.0, 1.0);
        freedom = std::clamp(freedom, 0.0, 1.0);
        risk = std::clamp(risk, 0.0, 1.0);
        lockAmount_ = std::clamp(lockAmount_ * 0.30 + memory * 0.70, 0.0, 0.98);
        double gameJump = 0.62 * freedom + 0.38 * risk;
        jumpiness_ = std::clamp(jumpiness_ * 0.28 + gameJump * 0.72, 0.02, 1.0);
        reverseOnLock_ = reverseOnLock_ || (lockAmount_ > 0.84 && risk > 0.62);
    }
    bool harmonicWeightEnabled() const { return harmonicWeightEnabled_; }
    double strongBeatPull() const { return strongBeatPull_; }
    RhythmModel rhythmModel() const { return rhythmModel_; }

    const char *rhythmModelName() const {
        switch (rhythmModel_) {
            case RhythmModel::Euclidean: return "euclidean";
            case RhythmModel::Stochastic: return "stochastic";
            case RhythmModel::Clustered: return "clustered";
            case RhythmModel::Irregular: return "irregular";
        }
        return "euclidean";
    }

    const char *harmonicModelName() const {
        switch (harmonicModel_) {
            case HarmonicModel::Modal: return "modal";
            case HarmonicModel::Functional: return "functional";
            case HarmonicModel::Jazz: return "jazz";
            case HarmonicModel::Chromatic: return "chromatic";
            case HarmonicModel::Drone: return "drone";
        }
        return "modal";
    }

private:
    // Seed-derived, same spirit as GenerativeArc::chooseTemplates(): the
    // scale passed into configure() is the piece's primary (the UI's
    // explicit choice, an instrument-tuning knob same as bpm -- kept, not
    // seed-overridden), but about 40% of the time the seed blends in a
    // second, genuinely different scale rather than leaving every piece
    // confined to a single fixed mode. +8000 keeps this draw off the same
    // RNG stream as note/rhythm generation below.
    void chooseScaleBlend(unsigned seed, double probability) {
        std::mt19937 blendRng(seed + 8000u);
        std::uniform_real_distribution<double> unit(0.0, 1.0);
        if (unit(blendRng) < std::clamp(probability, 0.0, 1.0)) {
            int count = static_cast<int>(Scale::Count);
            Scale secondary = scale_;
            // A second name is not necessarily a second sound: many entries
            // in the catalog are close rotations of the same seven-note
            // parent. Require at least four pitch-class membership changes
            // so a blend is an audible collision, not modal wallpaper.
            int attempts = 0;
            while ((secondary == scale_ || scaleDistance(scale_, secondary) < 4) && attempts++ < 128)
                secondary = static_cast<Scale>(static_cast<int>(unit(blendRng) * count) % count);
            hasSecondaryScale_ = secondary != scale_ && scaleDistance(scale_, secondary) >= 4;
            secondaryScale_ = secondary;
            blendAmount_ = hasSecondaryScale_ ? (0.20 + unit(blendRng) * 0.35) : 0.0;
        } else {
            hasSecondaryScale_ = false;
            blendAmount_ = 0.0;
        }
    }

    static int scaleDistance(Scale a, Scale b) {
        bool setA[12] = {};
        bool setB[12] = {};
        const auto &ta = scaleTable(a);
        const auto &tb = scaleTable(b);
        for (int i = 0; i < ta.length; ++i) setA[ta.degrees[static_cast<std::size_t>(i)] % 12] = true;
        for (int i = 0; i < tb.length; ++i) setB[tb.degrees[static_cast<std::size_t>(i)] % 12] = true;
        int distance = 0;
        for (int i = 0; i < 12; ++i) if (setA[i] != setB[i]) ++distance;
        return distance;
    }

    std::vector<bool> generateGate(double density, int pulses) {
        if (rhythmModel_ == RhythmModel::Euclidean)
            return euclideanRhythm(numSteps_, pulses);

        std::vector<bool> gate(static_cast<std::size_t>(numSteps_), false);
        std::uniform_real_distribution<double> unit(0.0, 1.0);

        if (rhythmModel_ == RhythmModel::Stochastic) {
            for (int i = 0; i < numSteps_; ++i)
                gate[static_cast<std::size_t>(i)] = unit(rng_) < density;
        } else if (rhythmModel_ == RhythmModel::Clustered) {
            int centre = static_cast<int>(unit(rng_) * numSteps_) % numSteps_;
            std::vector<int> candidates;
            candidates.reserve(static_cast<std::size_t>(numSteps_));
            for (int distance = 0; distance <= numSteps_ / 2; ++distance) {
                int right = (centre + distance) % numSteps_;
                int left = (centre - distance + numSteps_) % numSteps_;
                candidates.push_back(right);
                if (left != right) candidates.push_back(left);
            }
            // A little local disorder keeps this from becoming merely a
            // contiguous block while preserving a recognisable burst.
            for (std::size_t i = 1; i < candidates.size(); ++i) {
                if (unit(rng_) < 0.35) std::swap(candidates[i - 1], candidates[i]);
            }
            for (int i = 0; i < pulses && i < static_cast<int>(candidates.size()); ++i)
                gate[static_cast<std::size_t>(candidates[static_cast<std::size_t>(i)])] = true;
        } else {
            // Successive unequal gaps: the sequence advances by a changing
            // local period rather than distributing all onsets globally.
            int position = static_cast<int>(unit(rng_) * numSteps_) % numSteps_;
            int placed = 0;
            int guard = 0;
            double meanGap = static_cast<double>(numSteps_) / static_cast<double>(pulses);
            while (placed < pulses && guard++ < numSteps_ * 4) {
                if (!gate[static_cast<std::size_t>(position)]) {
                    gate[static_cast<std::size_t>(position)] = true;
                    ++placed;
                }
                int gap = std::max(1, static_cast<int>(std::round(meanGap * (0.45 + unit(rng_) * 1.25))));
                position = (position + gap) % numSteps_;
            }
        }

        int active = 0;
        for (bool value : gate) if (value) ++active;
        if (active == 0) gate[static_cast<std::size_t>(identityFallbackIndex_++ % numSteps_)] = true;
        if (active == numSteps_) gate.back() = false;
        return gate;
    }

    // Turing-Machine-flavoured character, seed-derived: lockAmount_ ranges
    // widely (many pieces stay near this engine's old fully-fresh-every-bar
    // behaviour, some develop a strongly persistent, slowly-mutating
    // theme), jumpiness_ likewise varies piece to piece (stepwise melodic
    // motion vs. free wide leaps), and reverseOnLock_ only ever gets a
    // chance to be true for the most locked pieces.
    void chooseSequenceCharacter(unsigned seed) {
        std::mt19937 charRng(seed + 9500u);
        std::uniform_real_distribution<double> u(0.0, 1.0);
        lockAmount_ = std::pow(u(charRng), 1.5); // biased toward lower values -- most pieces stay closer to fresh
        jumpiness_ = u(charRng);

        // Real voice leading, in absolute semitones from the previous note
        // actually played -- not the scale-DEGREE-index distance jumpiness_
        // above already shapes. The two are genuinely different measures:
        // a scale's degree steps are 1-3 semitones apiece depending on the
        // scale, and the existing octaveSteps random walk (below) can add
        // a full octave completely independent of jumpiness_'s weighting.
        // When this is on, it replaces the degree-index selection for the
        // whole piece: candidates are real MIDI notes across several
        // octaves, chosen from a three-bucket mixture (mostly a step of
        // 0-2 semitones, occasionally 3-6, rarely a genuine 7-18 semitone
        // leap) instead of a single decaying exponential -- continuous
        // melodic arcs that mostly breathe in small steps but can still
        // leap dramatically once in a while, DIY-modular "Brownian motion
        // melody generator" territory (Mutable Marbles' pitch section,
        // and the many ATtiny/Arduino clones of the same idea) rather than
        // this engine's existing per-scale-degree weighting.
        voiceLeadingEnabled_ = u(charRng) < 0.2;
        reverseOnLock_ = (lockAmount_ > 0.85) && (u(charRng) < 0.3);
        harmonicWeightEnabled_ = u(charRng) < 0.5;
        strongBeatPull_ = harmonicWeightEnabled_ ? (0.5 + u(charRng) * 1.5) : 0.0;

        // A real functional-harmony root movement, one chord per bar,
        // instead of the fixed I/III/V target the strong-beat weighting
        // above defaults to. Expressed as scale-degree indices (0-based)
        // rather than named roman numerals so the same handful of common
        // progressions work generically across every scale table (5-8
        // notes) -- indices simply wrap (mod table length) into whatever
        // scale is active, including after a mid-piece modulation/modal
        // shift. Only matters in pieces where harmonicWeightEnabled_ is
        // also true; harmless (silently unused) otherwise.
        // Expanded from the original 6 (fase 110, task #29 -- a real
        // cross-seed-repetition audit found this exact catalog: only 6
        // fixed progressions, so with enough pieces the SAME one (often
        // I-IV-V-I or I-vi-IV-V, the two most cliche progressions in
        // pop/rock harmony) recurs constantly, an audible source of the
        // sameness the user reported). The original 6 are unchanged in
        // place (seed->piece mapping for pieces that land on indices 0-5
        // is preserved); the new 8 add real, genuinely distinct root
        // motion -- a jazz turnaround (I-vi-ii-V), its own rotation
        // (vi-ii-V-I), a descending circle-of-fifths fragment through the
        // leading-tone diminished (I-IV-vii-iii, real and previously
        // absent -- vii never appeared in the original 6 at all), a real
        // stepwise descending bass walk (I-vii-vi-V), and rotations of
        // the Axis progression starting on a different degree so the
        // FIRST chord of the bar -- what a listener's ear anchors to --
        // varies too, not just which four chords cycle underneath.
        static const int progressions[][4] = {
            {0, 3, 4, 0},   // I-IV-V-I
            {0, 5, 3, 4},   // I-vi-IV-V
            {0, 4, 5, 3},   // I-V-vi-IV
            {1, 4, 0, 0},   // ii-V-I (repeats I to keep every pattern 4 long)
            {0, 3, 0, 4},   // I-IV-I-V
            {0, 2, 3, 4},   // I-iii-IV-V
            {0, 5, 1, 4},   // I-vi-ii-V (real jazz turnaround)
            {5, 1, 4, 0},   // vi-ii-V-I (same turnaround, minor-start rotation)
            {3, 0, 4, 5},   // IV-I-V-vi (Axis rotation, different opening chord)
            {5, 3, 0, 4},   // vi-IV-I-V (Axis rotation, minor-start)
            {0, 3, 6, 2},   // I-IV-vii-iii (leading-tone diminished, real descending-fifths fragment)
            {0, 6, 5, 4},   // I-vii-vi-V (real stepwise descending bass walk)
            {1, 3, 0, 4},   // ii-IV-I-V
            {0, 4, 1, 3},   // I-V-ii-IV
        };
        constexpr int kNumProgressions = static_cast<int>(sizeof(progressions) / sizeof(progressions[0]));
        chordProgressionEnabled_ = u(charRng) < 0.5;
        if (harmonicModel_ == HarmonicModel::Modal || harmonicModel_ == HarmonicModel::Drone)
            chordProgressionEnabled_ = false;
        // Functional/Chromatic pieces retain the seed-derived 50% choice;
        // Jazz always needs a moving harmonic bed for its chord-tone and
        // voice-leading language. The previous unconditional `else=true`
        // silently removed progression-free trajectories from most pieces.
        if (harmonicModel_ == HarmonicModel::Jazz) {
            chordProgressionEnabled_ = true;
            harmonicWeightEnabled_ = true;
            strongBeatPull_ = 1.1 + u(charRng) * 1.4;
            voiceLeadingEnabled_ = true;
        } else if (harmonicModel_ == HarmonicModel::Chromatic) {
            harmonicWeightEnabled_ = true;
            strongBeatPull_ = 0.6 + u(charRng) * 0.8;
            voiceLeadingEnabled_ = true;
        } else if (harmonicModel_ == HarmonicModel::Drone) {
            harmonicWeightEnabled_ = true;
            strongBeatPull_ = 1.4 + u(charRng);
            lockAmount_ = std::max(lockAmount_, 0.72);
        }
        if (chordProgressionEnabled_) {
            int choice;
            if (harmonicModel_ == HarmonicModel::Jazz) {
                static const int jazzChoices[] = {3, 6, 7, 10};
                choice = jazzChoices[static_cast<int>(u(charRng) * 4.0) % 4];
            } else {
                choice = static_cast<int>(u(charRng) * kNumProgressions) % kNumProgressions;
            }
            chordProgression_.assign(progressions[choice], progressions[choice] + 4);

            // Neo-Riemannian P/L/R (see NeoRiemannian.hpp): a fraction of
            // pieces that already have chord movement get a real
            // chromatic triad wandering via parsimonious voice leading
            // instead of the fixed roman-numeral list above -- mutually
            // exclusive per piece, same "one clean mode, not layered"
            // discipline as every other alternate-mode pair in this file.
            neoRiemannianEnabled_ = harmonicModel_ == HarmonicModel::Chromatic
                ? true : (harmonicModel_ == HarmonicModel::Functional && u(charRng) < 0.18);
            if (neoRiemannianEnabled_) {
                currentTriad_ = { mod12(rootMidiNote_), true }; // starts major on the tonic
            }
        }
    }

    static bool isChordTone(int degreeIndex, int currentChordDegreeIndex, int scaleLength) {
        int root = currentChordDegreeIndex % scaleLength;
        int third = (root + 2) % scaleLength;
        int fifth = (root + 4) % scaleLength;
        return degreeIndex == root || degreeIndex == third || degreeIndex == fifth;
    }
    // Needs the actual scale table (not just its length) to convert a
    // degree index into a real pitch class -- the Neo-Riemannian triad is
    // a fixed chromatic object, unrelated to which scale is active, so it
    // can only be checked against real pitch classes, not degree indices.
    bool isChordToneForTable(int degreeIndex, const ScaleTable &table) const {
        if (neoRiemannianEnabled_) {
            int pc = (rootMidiNote_ + table.degrees[static_cast<size_t>(degreeIndex)]) % 12;
            if (pc < 0) pc += 12;
            return triadContainsPc(currentTriad_, pc);
        }
        return isChordTone(degreeIndex, currentChordDegreeIndex_, table.length);
    }
    bool isChordTone(int degreeIndex, int scaleLength) const {
        return isChordTone(degreeIndex, currentChordDegreeIndex_, scaleLength);
    }

    // One "beat" = numSteps_/4 steps (a 16-step bar's four quarter-notes);
    // step 0 of each beat counts as strong. Falls back to "every step is
    // strong" if numSteps_ < 4 rather than dividing by zero.
    bool isStrongBeat(int step) const {
        int beatDiv = numSteps_ >= 4 ? numSteps_ / 4 : 1;
        return (step % beatDiv) == 0;
    }

    static bool isStableDegree(int degreeIndex, int scaleLength) {
        if (scaleLength <= 5) return degreeIndex == 0 || degreeIndex == 2;
        return degreeIndex == 0 || degreeIndex == 2 || degreeIndex == 4;
    }

    int numSteps_ = 16;
    Scale scale_ = Scale::MinorPentatonic;
    Scale secondaryScale_ = Scale::MinorPentatonic;
    bool hasSecondaryScale_ = false;
    double blendAmount_ = 0.0;
    bool customPrimary_ = false;
    ScaleTable customPrimaryTable_{};
    std::string customPrimaryDescription_;
    int rootMidiNote_ = 57; // A3
    int registerOffset_ = 0;
    std::vector<bool> gate_;
    std::vector<int> notes_;
    std::mt19937 rng_;
    KSRandomizerCore ksRandomizer_;

    double lockAmount_ = 0.0;
    double jumpiness_ = 1.0;
    bool reverseOnLock_ = false;
    bool harmonicWeightEnabled_ = false;
    double strongBeatPull_ = 0.0;
    RhythmModel rhythmModel_ = RhythmModel::Euclidean;
    HarmonicModel harmonicModel_ = HarmonicModel::Modal;
    int identityFallbackIndex_ = 0;
    bool chordProgressionEnabled_ = false;
    std::vector<int> chordProgression_;
    size_t chordStep_ = 0;
    int currentChordDegreeIndex_ = 0;
    int lastDegreeIndex_ = 0;
    int lastDegreeOffset_ = 0;
    bool firstRegenerate_ = false;

    bool neoRiemannianEnabled_ = false;
    Triad currentTriad_{};
    int neoRiemannianOpCount_ = 0;

    bool voiceLeadingEnabled_ = false;
    int lastMidiNote_ = 57;
    MelodicContourMemory contourMemory_;
    int phraseBarCount_ = 0;

    // Real semitone-distance voice leading (see voiceLeadingEnabled_ above):
    // builds every in-scale MIDI note within +-3 octaves of the root,
    // buckets them by absolute distance from lastMidiNote_, and rolls a
    // bucket (80% small step, 15% medium, 5% dramatic leap) before picking
    // uniformly within it. Falls back down the chain (small -> medium ->
    // leap -> any candidate) if the rolled bucket is empty for this scale/
    // register combination, so it always returns something rather than
    // ever needing to special-case "no candidates."
    int chooseVoiceLeadingNote(const ScaleTable &table) {
        std::vector<int> pitchClasses;
        for (int j = 0; j < table.length; ++j) {
            int pc = ((rootMidiNote_ + table.degrees[static_cast<size_t>(j)]) % 12 + 12) % 12;
            pitchClasses.push_back(pc);
        }
        std::vector<int> small, medium, leap, any;
        int rangeLow = rootMidiNote_ - 24, rangeHigh = rootMidiNote_ + 36;
        for (int n = rangeLow; n <= rangeHigh; ++n) {
            int pc = ((n % 12) + 12) % 12;
            bool inScale = false;
            for (int p : pitchClasses) if (p == pc) { inScale = true; break; }
            if (!inScale) continue;
            any.push_back(n);
            int dist = std::abs(n - lastMidiNote_);
            if (dist <= 2) small.push_back(n);
            else if (dist <= 6) medium.push_back(n);
            else if (dist <= 18) leap.push_back(n);
        }
        std::uniform_real_distribution<double> unit(0.0, 1.0);
        double roll = unit(rng_);
        const std::vector<int> *chosen = &any;
        if (roll < 0.80 && !small.empty()) chosen = &small;
        else if (roll < 0.95 && !medium.empty()) chosen = &medium;
        else if (!leap.empty()) chosen = &leap;
        else if (!small.empty()) chosen = &small;
        else if (!medium.empty()) chosen = &medium;
        std::uniform_int_distribution<size_t> pick(0, chosen->size() - 1);
        return (*chosen)[pick(rng_)];
    }
};

inline double midiToFreq(int midiNote) {
    return 440.0 * std::pow(2.0, (midiNote - 69) / 12.0);
}

} // namespace rasgo
